import 'package:cloud_firestore/cloud_firestore.dart';import 'package:firebase_auth/firebase_auth.dart';import 'package:flutter/material.dart';import 'product_service.dart';import 'edit_listing_screen.dart';class MyListingsScreen extends StatelessWidget{const MyListingsScreen({super.key});@override Widget build(BuildContext c){final uid=FirebaseAuth.instance.currentUser!.uid;return Scaffold(appBar:AppBar(title:const Text('Iklan Saya')),body:StreamBuilder<QuerySnapshot<Map<String,dynamic>>>(stream:FirebaseFirestore.instance.collection('products').where('sellerId',isEqualTo:uid).snapshots(),builder:(c,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());return ListView(children:s.data!.docs.map((d){final x=d.data();return ListTile(title:Text(x['title']??''),trailing:Row(mainAxisSize:MainAxisSize.min,children:[IconButton(icon:const Icon(Icons.edit),onPressed:()=>Navigator.push(c,MaterialPageRoute(builder:(_)=>EditListingScreen(id:d.id,data:x)))),IconButton(icon:const Icon(Icons.delete_outline),onPressed:()=>ProductService().deleteProduct(d.id,List<dynamic>.from(x['imageUrls']??[]))) ]));}).toList());}));}}